FROM vip_usermgmt.office_master om
JOIN vip_usermgmt.office_types ot ON ot.type_id = om.type_id
JOIN vip_usermgmt.organization_master org ON org.organization_id = ot.organization_id
WHERE om.office_name = 'RO-Kolkata' AND org.organization_code = 'NHAI'
AND NOT EXISTS (
  SELECT 1 FROM vip_usermgmt.division_master dm
  WHERE dm.division_name = 'PIU-Kharagpur' AND dm.office_id = om.office_id
);

