  om.office_id, dm.division_id
FROM vip_usermgmt.office_master om
JOIN vip_usermgmt.office_types ot ON ot.type_id = om.type_id
JOIN vip_usermgmt.organization_master org ON org.organization_id = ot.organization_id
JOIN vip_usermgmt.division_master dm ON dm.office_id = om.office_id AND dm.division_name = 'Highways'
WHERE om.office_name = 'Highway Division' AND org.organization_code = 'MORTH'
AND NOT EXISTS (
  SELECT 1 FROM vip_usermgmt.user_designation_master udm
  WHERE udm.designation_code = 'US' AND udm.office_master_id = om.office_id AND udm.division_id = dm.division_id
);

