-- Faim Saifi | MORTH > HO > RT&H > MO > DEO
UPDATE vip_usermgmt.vip_user_login_report SET
  organization = (SELECT organization_id FROM vip_usermgmt.organization_master WHERE organization_code = 'MORTH'),
  office = (SELECT om.office_id FROM vip_usermgmt.office_master om
    JOIN vip_usermgmt.office_types ot ON ot.type_id = om.type_id
    JOIN vip_usermgmt.organization_master org ON org.organization_id = ot.organization_id
    WHERE om.office_name = 'RT&H' AND org.organization_code = 'MORTH' LIMIT 1),
  designation = (SELECT udm.designation_id FROM vip_usermgmt.user_designation_master udm
    JOIN vip_usermgmt.office_master om ON om.office_id = udm.office_master_id
    JOIN vip_usermgmt.division_master dm ON dm.division_id = udm.division_id
    WHERE udm.designation_code = 'DEO' AND om.office_name = 'RT&H' AND dm.division_name = 'MO' LIMIT 1)
WHERE login_id = 'DEO-Eng';

