   WHERE om.office_name = 'RO-Port Blair' AND org.organization_code = 'NHIDCL' LIMIT 1),
  designation = (SELECT udm.designation_id FROM vip_usermgmt.user_designation_master udm
   JOIN vip_usermgmt.office_master om ON om.office_id = udm.office_master_id
   JOIN vip_usermgmt.division_master dm ON dm.division_id = udm.division_id
   WHERE udm.designation_code = 'ED' AND om.office_name = 'RO-Port Blair' AND dm.division_name = 'Port Blair' LIMIT 1)
WHERE login_id = 'NHIDCL-RO-Port Blair';

